import java.util.Scanner;

class FindNumber {

    boolean checkEven(int number) {

        if (number % 2 == 0) {
            return true;
        }

        return false;
    }
}

class EvenApp {

    public static void main(String[] args) {

        Scanner scan = new Scanner(System.in);

        System.out.println("Enter a number:");
        int number = scan.nextInt();

        FindNumber findNumber =
                new FindNumber();

        boolean result =
                findNumber.checkEven(number);

        if (result == true) {
            System.out.println("Even");
        }
    }
}

import java.util.Scanner;

class FindNumber {

    boolean checkDivisibility(int number) {

        if (number % 2 == 0 &&
            number % 4 == 0) {

            return true;
        }

        return false;
    }
}

class EvenApp {

    public static void main(String[] args) {

        Scanner scan = new Scanner(System.in);

        System.out.println("Enter a number:");
        int number = scan.nextInt();

        FindNumber findNumber =
                new FindNumber();

        boolean result =
                findNumber.checkDivisibility(number);

        if (result == true) {
            System.out.println(
                "Divisible by 2 and 4"
            );
        } else {
            System.out.println(
                "Not divisible by 2 and 4"
            );
        }
    }
}

